"""
MythTV Server API Python Client Library
Provides a clean interface to interact with MythTV backend services.
"""

import requests
import json
from typing import Dict, List, Optional, Any, Union
from datetime import datetime, timedelta
from urllib.parse import urljoin, quote
import logging

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)


class MythTVError(Exception):
    """Base exception for MythTV API errors"""
    pass


class MythTVConnectionError(MythTVError):
    """Raised when connection to MythTV server fails"""
    pass


class MythTVAPIError(MythTVError):
    """Raised when API returns an error"""
    pass


class MythTVClient:
    """Main client for interacting with MythTV backend API"""

    def __init__(self, host: str = "localhost", port: int = 6544, 
                 username: Optional[str] = None, password: Optional[str] = None,
                 timeout: int = 30, verify_ssl: bool = True):
        """
        Initialize MythTV client

        Args:
            host: MythTV backend hostname or IP
            port: MythTV backend port (default: 6544)
            username: Optional username for authentication
            password: Optional password for authentication
            timeout: Request timeout in seconds
            verify_ssl: Whether to verify SSL certificates
        """
        self.host = host
        self.port = port
        self.base_url = f"http://{host}:{port}"
        self.timeout = timeout
        self.verify_ssl = verify_ssl

        self.session = requests.Session()
        if username and password:
            self.session.auth = (username, password)

        # Initialize service endpoints
        self.dvr = DVRService(self)
        self.video = VideoService(self)
        self.content = ContentService(self)
        self.guide = GuideService(self)
        self.channel = ChannelService(self)
        self.myth = MythService(self)
        self.capture = CaptureService(self)

    def _make_request(self, method: str, endpoint: str, 
                     params: Optional[Dict] = None,
                     data: Optional[Dict] = None) -> Dict[str, Any]:
        """
        Make HTTP request to MythTV API

        Args:
            method: HTTP method (GET, POST, etc.)
            endpoint: API endpoint path
            params: Query parameters
            data: Request body data

        Returns:
            Response data as dictionary
        """
        url = urljoin(self.base_url, endpoint)

        try:
            response = self.session.request(
                method=method,
                url=url,
                params=params,
                json=data,
                timeout=self.timeout,
                verify=self.verify_ssl
            )
            response.raise_for_status()

            # MythTV returns JSON or XML, try JSON first
            try:
                return response.json()
            except json.JSONDecodeError:
                # Return raw text if not JSON
                return {"response": response.text}

        except requests.exceptions.ConnectionError as e:
            raise MythTVConnectionError(f"Failed to connect to MythTV server: {e}")
        except requests.exceptions.Timeout as e:
            raise MythTVConnectionError(f"Request timed out: {e}")
        except requests.exceptions.HTTPError as e:
            raise MythTVAPIError(f"API request failed: {e}")

    def get(self, endpoint: str, params: Optional[Dict] = None) -> Dict[str, Any]:
        """Make GET request"""
        return self._make_request("GET", endpoint, params=params)

    def post(self, endpoint: str, data: Optional[Dict] = None) -> Dict[str, Any]:
        """Make POST request"""
        return self._make_request("POST", endpoint, data=data)

    def test_connection(self) -> bool:
        """Test connection to MythTV server"""
        try:
            self.myth.get_hostname()
            return True
        except Exception as e:
            logger.error(f"Connection test failed: {e}")
            return False


