        """Get storage group directories"""
        params = {}
        if group_name:
            params["GroupName"] = group_name
        if hostname:
            params["HostName"] = hostname
        return self.client.get(f"{self.base_path}/GetStorageGroupDirs", params)

    def get_setting(self, key: str, hostname: Optional[str] = None,
                   default: Optional[str] = None) -> str:
        """
        Get a MythTV setting value

        Args:
            key: Setting key
            hostname: Specific hostname (None for global)
            default: Default value if not found
        """
        params = {"Key": key}
        if hostname:
            params["HostName"] = hostname
        if default:
            params["Default"] = default

        result = self.client.get(f"{self.base_path}/GetSetting", params)
